async function consultarCEP(cep, signal) {
  const digits = String(cep).replace(/\D/g, '');
  if (!/^\d{8}$/.test(digits)) throw new Error('CEP deve ter 8 dígitos');
  const res = await fetch(`https://viacep.com.br/ws/${digits}/json/`, {signal});
  if (!res.ok) throw new Error('Serviço de CEP indisponível');
  const d = await res.json();
  if (d.erro) throw new Error('CEP não encontrado');
  return {rua:d.logradouro||'', bairro:d.bairro||'', cidade:d.localidade||'', uf:d.uf||''};
}
