function mostrarAnuncio(container, anuncio) {
  const artigo = document.createElement('article');
  const titulo = document.createElement('h3');
  const descricao = document.createElement('p');
  titulo.textContent = String(anuncio.title || 'Sem título');
  descricao.textContent = String(anuncio.description || '');
  artigo.append(titulo,descricao);
  container.replaceChildren(artigo);
}

#!/usr/bin/env bash
set -euo pipefail
[[ $# -eq 1 && -f "$1" ]] || { echo 'Uso: bash converter.sh filme.webm'; exit 1; }
command -v ffmpeg >/dev/null || { echo 'Instale o FFmpeg: pkg install ffmpeg'; exit 1; }
ORIGEM="$1"; SAIDA="${ORIGEM%.*}.mp4"
[[ ! -e "$SAIDA" ]] || { echo 'Arquivo de destino já existe; não vou substituir.'; exit 1; }
ffmpeg -nostdin -i "$ORIGEM" -c:v libx264 -pix_fmt yuv420p -c:a aac -movflags +faststart "$SAIDA"
echo "Salvo: $SAIDA"
